SELECT d.TASK_DEPENDENCY_ID AS row_id, d.ACTIVE_FLAG AS active_flag, CASE WHEN d.PIPELINE_ID = t.PIPELINE_ID AND COALESCE(d.DEPENDS_ON_PIPELINE_ID, u.PIPELINE_ID) = u.PIPELINE_ID THEN 'Y' ELSE 'N' END AS well_formed, d.TASK_ID AS task_id, d.DEPENDS_ON_TASK_ID AS depends_on_task_id, p.PIPELINE_CODE AS pipeline_code, t.TASK_CODE AS task_code, up.PIPELINE_CODE AS depends_on_pipeline_code, u.TASK_CODE AS depends_on_task_code, CASE WHEN p.PROJECT_ID=up.PROJECT_ID THEN NULL ELSE upstream_project.PROJECT_CODE END AS depends_on_project_code, d.DEPENDENCY_TYPE AS dependency_type, d.CONSUME_REPAIRS AS consume_repairs FROM CFG_TASK_DEPENDENCY d JOIN CFG_TASKS t ON t.TASK_ID = d.TASK_ID JOIN CFG_PIPELINES p ON p.PIPELINE_ID = t.PIPELINE_ID JOIN CFG_TASKS u ON u.TASK_ID = d.DEPENDS_ON_TASK_ID JOIN CFG_PIPELINES up ON up.PIPELINE_ID = u.PIPELINE_ID JOIN CFG_PROJECTS upstream_project ON upstream_project.PROJECT_ID=up.PROJECT_ID WHERE p.PROJECT_ID=:project_id ORDER BY 1
